"""What an organization's auto-generated file relation search can filter and order by, and how its row becomes data."""

from __future__ import annotations

from typing import override

from ai.backend.common.data.entity.types import RuntimeEntityID
from ai.backend.manager.data.auto_generated_file.types import (
    OrganizationAutoGeneratedFileRelationData,
)
from ai.backend.manager.models.organization_auto_generated_file_relation.row import (
    OrganizationAutoGeneratedFileRelationRow,
)
from ai.backend.manager.models.specs.conditions.string import StringConditions
from ai.backend.manager.models.specs.conditions.uuid import UUIDConditions
from ai.backend.manager.models.specs.orders.column import ColumnOrder
from ai.backend.manager.models.specs.search.converter import RowDataConverter
from ai.backend.manager.models.specs.search.field import SearchableField


class _OrganizationAutoGeneratedFileRelationOwnFields(
    RowDataConverter[
        OrganizationAutoGeneratedFileRelationRow, OrganizationAutoGeneratedFileRelationData
    ]
):
    organization_type = SearchableField(
        OrganizationAutoGeneratedFileRelationRow.organization_type,
        StringConditions(OrganizationAutoGeneratedFileRelationRow.organization_type),
        ColumnOrder(OrganizationAutoGeneratedFileRelationRow.organization_type),
    )
    organization_id = SearchableField(
        OrganizationAutoGeneratedFileRelationRow.organization_id,
        UUIDConditions(OrganizationAutoGeneratedFileRelationRow.organization_id),
        ColumnOrder(OrganizationAutoGeneratedFileRelationRow.organization_id),
    )
    file_id = SearchableField(
        OrganizationAutoGeneratedFileRelationRow.file_id,
        UUIDConditions(OrganizationAutoGeneratedFileRelationRow.file_id),
        ColumnOrder(OrganizationAutoGeneratedFileRelationRow.file_id),
    )
    path = SearchableField(
        OrganizationAutoGeneratedFileRelationRow.path,
        StringConditions(OrganizationAutoGeneratedFileRelationRow.path),
        ColumnOrder(OrganizationAutoGeneratedFileRelationRow.path),
    )
    perm = SearchableField(OrganizationAutoGeneratedFileRelationRow.perm, None, None)

    @override
    def to_data(
        self, row: OrganizationAutoGeneratedFileRelationRow
    ) -> OrganizationAutoGeneratedFileRelationData:
        return OrganizationAutoGeneratedFileRelationData(
            organization=RuntimeEntityID(
                self.organization_type.read(row), self.organization_id.read(row)
            ),
            file_id=self.file_id.read(row),
            path=self.path.read(row),
            perm=self.perm.read(row),
        )


class OrganizationAutoGeneratedFileRelationSearchableFields:
    own = _OrganizationAutoGeneratedFileRelationOwnFields()
